insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('energy-budget-weekday-planner', 'Energy Budget Weekday Planner', 'worksheet'::resource_kind, 'A one-page plan that spreads a client''s limited energy across the days of a week.', 'Use it to match demanding tasks with the hours a client has the most energy.', array['Adults']::text[], '20 minutes', 'Have the client mark energy highs and lows first, then place tasks. Expect them to overfill Monday; invite them to leave one open block each day. Review next session and let them decide what to move, not what to drop.', '[{"id": "f0", "type": "textarea", "label": "Which hours of the day do I have the most energy?"}, {"id": "f1", "type": "textarea", "label": "Which tasks cost me the most energy this week?"}, {"id": "f2", "type": "textarea", "label": "Which tasks give energy back?"}, {"id": "f3", "type": "textarea", "label": "Where will I leave open space on purpose?"}, {"id": "f4", "type": "textarea", "label": "What will I move or ask for help with?"}]'::jsonb, array['energy', 'planning', 'pacing']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('decision-pause-and-pros-page', 'Decision Pause and Pros Page', 'worksheet'::resource_kind, 'A page for slowing a hard choice into options, what matters, and one small next move.', 'Use it to help a client choose without rushing or freezing.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through the page in session with a real decision. Clients who freeze often list only one option, so ask for a third. Close by naming one small step that keeps the choice open. The decision stays theirs throughout.', '[{"id": "f0", "type": "textarea", "label": "The choice I am facing is..."}, {"id": "f1", "type": "textarea", "label": "Three options, including one I have not said out loud:"}, {"id": "f2", "type": "textarea", "label": "What matters most to me here?"}, {"id": "f3", "type": "textarea", "label": "What I would want to know before deciding:"}, {"id": "f4", "type": "textarea", "label": "One small step I can take this week:"}]'::jsonb, array['decision making', 'values', 'planning']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('weekly-win-collector-sheet', 'Weekly Win Collector Sheet', 'worksheet'::resource_kind, 'A weekly sheet for catching small things that went acceptably, however ordinary.', 'Use it to help a client notice what is working alongside what is hard.', array['Adults', 'Teens']::text[], '10 minutes daily for one week', 'Ask the client to fill one line each evening, even if the entry is tiny. If they say nothing happened, ask what they got through. Read the sheet together next session and look for patterns in what helps.', '[{"id": "f0", "type": "textarea", "label": "Monday win:"}, {"id": "f1", "type": "textarea", "label": "Tuesday win:"}, {"id": "f2", "type": "textarea", "label": "Wednesday win:"}, {"id": "f3", "type": "textarea", "label": "Thursday through Sunday wins:"}, {"id": "f4", "type": "textarea", "label": "What do these wins have in common?"}, {"id": "f5", "type": "textarea", "label": "What helped each one happen?"}]'::jsonb, array['strengths', 'reflection', 'daily log']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('transition-ritual-builder-page', 'Transition Ritual Builder Page', 'worksheet'::resource_kind, 'A page for designing a short ritual that marks the shift between work and home.', 'Use it to help a client leave one role behind before stepping into the next.', array['Adults']::text[], '20 minutes', 'Ask for a ritual that takes five minutes or less and fits the client''s real commute or routine. Have them test it for a week and report back. If it feels forced, invite them to change it; the point is a clear signal, not perfection.', '[{"id": "f0", "type": "textarea", "label": "The two roles I move between are..."}, {"id": "f1", "type": "textarea", "label": "What I usually carry from one into the other:"}, {"id": "f2", "type": "textarea", "label": "A five-minute action that could mark the change:"}, {"id": "f3", "type": "textarea", "label": "Where and when I will do it:"}, {"id": "f4", "type": "textarea", "label": "How I will know it helped:"}]'::jsonb, array['transitions', 'routine', 'work-life balance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('support-circle-contact-sheet', 'Support Circle Contact Sheet', 'worksheet'::resource_kind, 'A sheet that lists who a client can reach out to, for what, and by which route.', 'Use it to make a client''s real support easier to reach on a hard day.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill it in session so names and numbers are real. Many clients list people they would not actually call; ask who they would. Offer to role-play the first message. If the client mentions crisis, remind them they can call or text 988 at any time.', '[{"id": "f0", "type": "textarea", "label": "Someone I can talk to when I feel overwhelmed:"}, {"id": "f1", "type": "textarea", "label": "Someone who helps with practical things:"}, {"id": "f2", "type": "textarea", "label": "Someone who makes me laugh:"}, {"id": "f3", "type": "textarea", "label": "How I like to reach each person (call, text, in person):"}, {"id": "f4", "type": "textarea", "label": "If I ever feel unsafe, I can call or text 988."}, {"id": "f5", "type": "textarea", "label": "One person I will contact this week and why:"}]'::jsonb, array['support network', 'connection', 'asking for help']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-with-a-backup-plan', 'Behavioral Experiment With a Backup Plan', 'cbt'::resource_kind, 'A planner for testing a feared prediction and naming a backup plan before the test.', 'Use it to help a client test a prediction with a plan for if it goes poorly.', array['Adults', 'Teens']::text[], '30 minutes', 'Agree on a prediction specific enough to check and rate belief before and after. The backup plan matters: clients try the experiment more readily when they know what they will do if it goes badly. Review what happened without grading it.', '[{"id": "f0", "type": "textarea", "label": "My prediction is..."}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The experiment I will try:"}, {"id": "f3", "type": "textarea", "label": "My backup plan if it goes poorly:"}, {"id": "f4", "type": "textarea", "label": "What actually happened:"}, {"id": "f5", "type": "textarea", "label": "What I make of that now:"}]'::jsonb, array['behavioral experiment', 'prediction', 'CBT']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('zoom-out-ladder-for-hot-thoughts', 'Zoom-Out Ladder for Hot Thoughts', 'cbt'::resource_kind, 'A ladder that moves a client from a hot thought to a wider, steadier view in small steps.', 'Use it to help a client step back from a strong thought one rung at a time.', array['Adults', 'Teens']::text[], '25 minutes', 'Start with a recent moment and the thought that spiked. Each rung asks for a wider view: a friend''s view, a year from now, the full picture. Clients may skip rungs; slow them down and let each answer land before the next.', '[{"id": "f0", "type": "textarea", "label": "The hot thought I had was..."}, {"id": "f1", "type": "textarea", "label": "How would a friend describe this moment?"}, {"id": "f2", "type": "textarea", "label": "How might this look a year from now?"}, {"id": "f3", "type": "textarea", "label": "What facts am I leaving out?"}, {"id": "f4", "type": "textarea", "label": "A wider thought I can try on:"}]'::jsonb, array['cognitive restructuring', 'perspective', 'thoughts']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('thinking-trap-spotter-checklist', 'Thinking Trap Spotter Checklist', 'cbt'::resource_kind, 'A checklist of common thinking traps for a client to tick as they review a rough moment.', 'Use it to give a client words for the patterns in their own thinking.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through the traps with an example from the client''s week. Encourage curiosity over self-criticism: spotting a trap is useful whether or not they agree with the thought. A client who ticks every box may need a smaller list.', '[{"id": "f0", "type": "textarea", "label": "The moment I am looking at:"}, {"id": "f1", "type": "textarea", "label": "Traps I notice in my thinking (all-or-nothing, mind reading, and so on):"}, {"id": "f2", "type": "textarea", "label": "Which one shows up most often for me?"}, {"id": "f3", "type": "textarea", "label": "A question I can ask myself when it appears:"}]'::jsonb, array['thinking traps', 'cognitive distortions', 'awareness']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('compassionate-coach-reframe-page', 'Compassionate Coach Reframe Page', 'cbt'::resource_kind, 'A page for rewriting a harsh thought in the voice of a kind, honest coach.', 'Use it to help a client reply to self-criticism with firm, warm language.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write the harsh line first, then how a coach who believed in them would put it. If the coach sounds fake, aim for honest rather than cheerful. Let them read it aloud and say whether it feels believable.', '[{"id": "f0", "type": "textarea", "label": "The harsh thing I told myself:"}, {"id": "f1", "type": "textarea", "label": "What a fair, kind coach would say instead:"}, {"id": "f2", "type": "textarea", "label": "What this coach would want me to do next:"}, {"id": "f3", "type": "textarea", "label": "How believable the new line feels (0 to 10):"}]'::jsonb, array['self-compassion', 'self-talk', 'cognitive restructuring']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('worry-outcomes-estimate-sheet', 'Worry Outcomes Estimate Sheet', 'cbt'::resource_kind, 'A sheet that lists a feared outcome, other likely outcomes, and how coping might go.', 'Use it to widen a client''s view of what could happen and how they might handle it.', array['Adults']::text[], '25 minutes', 'Ask for the feared outcome, then two or three other outcomes, including a middle one. Finish with how the client has coped with something hard before. The aim is a fuller picture, not a promise that things will be fine.', '[{"id": "f0", "type": "textarea", "label": "The outcome I fear most:"}, {"id": "f1", "type": "textarea", "label": "Other things that could happen:"}, {"id": "f2", "type": "textarea", "label": "The most likely outcome, in my best estimate:"}, {"id": "f3", "type": "textarea", "label": "If the feared outcome did happen, how I would cope:"}]'::jsonb, array['worry', 'prediction', 'catastrophizing']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('values-anchor-wallet-card', 'Values Anchor Wallet Card', 'act'::resource_kind, 'A small card a client fills in with a value, a reminder and one action to carry with them.', 'Use it to keep a chosen value within reach during the day.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client choose one value that matters this month and write it in their own words. Keep the action small and observable. Suggest they keep it where they will see it, then ask next session when they used it.', '[{"id": "f0", "type": "textarea", "label": "A value I want to live by this month:"}, {"id": "f1", "type": "textarea", "label": "In my own words, it means..."}, {"id": "f2", "type": "textarea", "label": "A small action that fits it:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card:"}]'::jsonb, array['values', 'committed action', 'reminders']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('unhooking-phrase-practice-log', 'Unhooking Phrase Practice Log', 'act'::resource_kind, 'A log for trying phrases that create distance from sticky thoughts and noting what shifts.', 'Use it to help a client practice defusion with their own thoughts.', array['Adults', 'Teens']::text[], 'One week', 'Teach one or two phrases, such as I am having the thought that, and let the client choose wording that suits them. Defusion is not about making a thought go away; ask what changes in how much it pulls at them.', '[{"id": "f0", "type": "textarea", "label": "A sticky thought that showed up:"}, {"id": "f1", "type": "textarea", "label": "The phrase I tried on it:"}, {"id": "f2", "type": "textarea", "label": "What changed, if anything?"}, {"id": "f3", "type": "textarea", "label": "What I did next:"}, {"id": "f4", "type": "textarea", "label": "Which phrase I want to keep:"}]'::jsonb, array['defusion', 'cognitive fusion', 'practice']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('making-room-body-scan-page', 'Making Room Body Scan Page', 'act'::resource_kind, 'A page for noticing where a feeling sits in the body and making room for it while acting on values.', 'Use it to help a client make room for discomfort and still move toward what matters.', array['Adults']::text[], '25 minutes', 'Lead a short scan, then have the client describe the feeling like a curious observer: shape, edges, movement. Invite breathing around it, not into it. Some clients use this to get rid of the feeling; gently name the difference.', '[{"id": "f0", "type": "textarea", "label": "Where I feel it in my body:"}, {"id": "f1", "type": "textarea", "label": "If it had a shape, size or color, it would be..."}, {"id": "f2", "type": "textarea", "label": "What it feels like to make room for it:"}, {"id": "f3", "type": "textarea", "label": "What I want to do next, with it along:"}]'::jsonb, array['acceptance', 'willingness', 'body awareness']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('chessboard-self-reflection-page', 'Chessboard Self Reflection Page', 'act'::resource_kind, 'A page built on the chessboard metaphor: the pieces are thoughts, the board is the observing self.', 'Use it to help a client see thoughts and feelings as pieces, not the whole of them.', array['Adults']::text[], '25 minutes', 'Introduce the metaphor briefly, then let the client sort their current thoughts into the two sides. Ask who is holding the board. Do not push for a single right answer; the exercise is a shift in view.', '[{"id": "f0", "type": "textarea", "label": "Pieces on one side (thoughts I fight):"}, {"id": "f1", "type": "textarea", "label": "Pieces on the other side (thoughts I rely on):"}, {"id": "f2", "type": "textarea", "label": "What it is like to be the board instead of a piece:"}, {"id": "f3", "type": "textarea", "label": "One thing I can do while the pieces keep moving:"}]'::jsonb, array['self as context', 'observing self', 'metaphor']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('tiny-values-step-self-contract', 'Tiny Values Step Self-Contract', 'act'::resource_kind, 'A short contract with oneself that turns a value into one small step, with a plan for obstacles.', 'Use it to help a client choose one small, doable action tied to a value.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the step small enough that the client rates their confidence at 8 or more. Name the obstacles that usually show up and what willingness would look like. Check back in a week, and treat a missed step as information.', '[{"id": "f0", "type": "textarea", "label": "The value behind this step:"}, {"id": "f1", "type": "textarea", "label": "The one small step I will take, and when:"}, {"id": "f2", "type": "textarea", "label": "What might get in the way:"}, {"id": "f3", "type": "textarea", "label": "How I will make room for that:"}, {"id": "f4", "type": "textarea", "label": "Who I will tell about my step:"}]'::jsonb, array['committed action', 'values', 'barriers']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-menu-by-intensity', 'Distress Tolerance Menu by Intensity', 'dbt'::resource_kind, 'A menu that sorts distress skills by how intense the moment is, from mild to peak.', 'Use it to help a client reach for a skill that fits the size of the moment.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the menu in session with the client''s own favorites, grouped by intensity. High-intensity skills should be quick and physical. Rehearse picking one from the menu when calm so it is easy to find later.', '[{"id": "f0", "type": "textarea", "label": "Skills I can use when the feeling is mild:"}, {"id": "f1", "type": "textarea", "label": "Skills for when it is medium:"}, {"id": "f2", "type": "textarea", "label": "Skills for when it is at its peak:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this menu:"}]'::jsonb, array['distress tolerance', 'skills', 'toolbox']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('emotion-mind-check-in-dial', 'Emotion Mind Check-In Dial', 'dbt'::resource_kind, 'A dial from emotion mind through wise mind to reasonable mind for checking in several times a day.', 'Use it to help a client name which mind is driving at the moment.', array['Adults', 'Teens']::text[], 'One week', 'Have the client rate their current state a few times a day and note what the moment was. Look at the week for times of day or situations that pull them to either end. Wise mind is a blend, not a midpoint to hit.', '[{"id": "f0", "type": "textarea", "label": "Where the dial points right now and why:"}, {"id": "f1", "type": "textarea", "label": "What happened just before:"}, {"id": "f2", "type": "textarea", "label": "What my wise mind might say:"}, {"id": "f3", "type": "textarea", "label": "What I choose to do next:"}]'::jsonb, array['wise mind', 'emotion regulation', 'check-in']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('validation-levels-practice-page', 'Validation Levels Practice Page', 'dbt'::resource_kind, 'A page for practicing the levels of validation with a friend, partner or family member.', 'Use it to help a client practice listening and reflecting before offering advice.', array['Adults']::text[], '25 minutes', 'Pick one conversation to rehearse and role-play it in session. Ask the client to try reflecting, then naming what makes sense about the other person''s view. Self-validation can go on the same page.', '[{"id": "f0", "type": "textarea", "label": "Someone I want to validate this week:"}, {"id": "f1", "type": "textarea", "label": "What I will reflect back to show I heard them:"}, {"id": "f2", "type": "textarea", "label": "What makes sense about their feelings:"}, {"id": "f3", "type": "textarea", "label": "How I can validate myself in a hard moment:"}]'::jsonb, array['validation', 'interpersonal effectiveness', 'communication']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('opposite-action-week-planner', 'Opposite Action Week Planner', 'dbt'::resource_kind, 'A planner for choosing an emotion, naming its urge, and acting opposite when the urge does not fit the facts.', 'Use it to help a client try opposite action in small, planned moments.', array['Adults', 'Teens']::text[], 'One week', 'Pick a milder situation to start, where the emotion''s urge does not fit the facts. Have the client go all the way in with body posture and tone. Review what happened without judging the outcome.', '[{"id": "f0", "type": "textarea", "label": "The emotion and its urge:"}, {"id": "f1", "type": "textarea", "label": "Does the urge fit the facts? What does the evidence say?"}, {"id": "f2", "type": "textarea", "label": "What the opposite action would be:"}, {"id": "f3", "type": "textarea", "label": "When I will try it this week:"}, {"id": "f4", "type": "textarea", "label": "What happened:"}]'::jsonb, array['opposite action', 'emotion regulation', 'DBT skills']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('mindful-walking-checklist', 'Mindful Walking Checklist', 'dbt'::resource_kind, 'A checklist for a short, mindful walk that builds the habit of coming back to the present.', 'Use it to give a client an easy, repeatable way to practice one-mindfulness.', array['Adults', 'Teens']::text[], '10 minutes daily', 'Have the client choose one sense to focus on per walk and note when attention wandered and returned. Returning is the practice, so a wandering mind is not a mistake. Keep it short and do it in session once.', '[{"id": "f0", "type": "textarea", "label": "Where I walked and for how long:"}, {"id": "f1", "type": "textarea", "label": "What I noticed with my eyes, ears and feet:"}, {"id": "f2", "type": "textarea", "label": "How many times my mind wandered, and how I came back:"}, {"id": "f3", "type": "textarea", "label": "How I feel afterward compared with before:"}]'::jsonb, array['mindfulness', 'present moment', 'DBT skills']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('state-of-the-union-agenda-card', 'State of the Union Agenda Card', 'couples'::resource_kind, 'A short weekly agenda card for two partners to appreciate, check in and plan together.', 'Use it to give a couple a predictable, low-pressure time to talk.', array['Couples']::text[], '30 minutes weekly', 'Each partner fills in their half before the meeting. Keep the agenda small: appreciation, one thing that went well, one thing to adjust, one plan. Stop at the time limit even if topics remain; the habit matters more than finishing.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated about us this week:"}, {"id": "f1", "type": "textarea", "label": "Partner A: one thing I would like us to adjust:"}, {"id": "f2", "type": "textarea", "label": "Partner B: something I appreciated about us this week:"}, {"id": "f3", "type": "textarea", "label": "Partner B: one thing I would like us to adjust:"}, {"id": "f4", "type": "textarea", "label": "Together: one plan for the coming week:"}]'::jsonb, array['check-in', 'appreciation', 'weekly review']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('shared-calendar-fairness-review', 'Shared Calendar Fairness Review', 'couples'::resource_kind, 'A review of who plans, remembers and does what, so a couple can rebalance on purpose.', 'Use it to help a couple see and share the invisible work of running a home.', array['Couples']::text[], '40 minutes', 'Each partner lists what they believe they carry, then they compare. Expect surprise, and keep tone curious. The goal is a rebalance both can live with, not a perfect split; ask for one change each.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I plan or remember that few people see:"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I plan or remember that few people see:"}, {"id": "f2", "type": "textarea", "label": "Where our lists surprised each of us:"}, {"id": "f3", "type": "textarea", "label": "One task each of us will take on or hand over:"}, {"id": "f4", "type": "textarea", "label": "When we will review how it is going:"}]'::jsonb, array['mental load', 'household tasks', 'fairness']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('gratitude-handoff-evening-ritual', 'Gratitude Handoff Evening Ritual', 'couples'::resource_kind, 'A two-minute evening ritual where each partner hands the other one specific thank-you.', 'Use it to build a small daily habit of noticing each other.', array['Couples']::text[], 'Two minutes nightly for two weeks', 'Keep thank-yous specific and about something the partner did, not who they are. Have partners log them briefly. Notice if one partner struggles; talk about what makes it hard without pushing for more.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I thanked my partner for:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I thanked my partner for:"}, {"id": "f2", "type": "textarea", "label": "What it was like to hear it:"}, {"id": "f3", "type": "textarea", "label": "What we want to keep doing:"}]'::jsonb, array['appreciation', 'gratitude', 'ritual']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('cool-down-signal-agreement', 'Cool-Down Signal Agreement', 'couples'::resource_kind, 'A written agreement on a signal for pausing a heated talk and how to come back to it.', 'Use it to give a couple a shared way to pause before things get worse.', array['Couples']::text[], '30 minutes', 'Both partners choose the signal, the length of the break and who restarts. Practice calling a pause in session when calm. The pause is for settling, not for avoiding the topic, so name a time to return.', '[{"id": "f0", "type": "textarea", "label": "Partner A: signs that I am getting too heated:"}, {"id": "f1", "type": "textarea", "label": "Partner B: signs that I am getting too heated:"}, {"id": "f2", "type": "textarea", "label": "The signal we will use:"}, {"id": "f3", "type": "textarea", "label": "What each of us will do during the break:"}, {"id": "f4", "type": "textarea", "label": "When and how we will come back to the topic:"}]'::jsonb, array['de-escalation', 'conflict', 'repair']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('dream-together-mapping-page', 'Dream Together Mapping Page', 'couples'::resource_kind, 'A page where partners each map a hope for the next year and look for overlap.', 'Use it to help a couple talk about the future as a shared project.', array['Couples']::text[], '35 minutes', 'Each partner lists hopes separately, then shares. Look for the meaning under each hope rather than negotiating details. Differences are common; invite each partner to ask about the story behind the other''s dream.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a hope I have for the next year:"}, {"id": "f1", "type": "textarea", "label": "Partner B: a hope I have for the next year:"}, {"id": "f2", "type": "textarea", "label": "The meaning behind each hope:"}, {"id": "f3", "type": "textarea", "label": "Where our hopes overlap:"}, {"id": "f4", "type": "textarea", "label": "One step we can take toward a shared hope:"}]'::jsonb, array['shared meaning', 'goals', 'connection']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('feelings-forecast-window-drawing', 'Feelings Forecast Window Drawing', 'kids'::resource_kind, 'The child draws a window and fills it with the weather that matches how they feel today.', 'Use it to give a child a simple picture for naming feelings.', array['Children']::text[], '25 minutes', 'Give the child paper, crayons and a frame. Ask what weather fits today and let them draw it. The parent joins in by drawing their own window and shares it. Keep it playful; there are no wrong weather reports.', '[{"id": "f0", "type": "textarea", "label": "Draw the weather that matches how I feel today"}, {"id": "f1", "type": "textarea", "label": "What the weather is called"}, {"id": "f2", "type": "textarea", "label": "Draw what my window looked like yesterday"}, {"id": "f3", "type": "textarea", "label": "What my grown-up''s weather is today"}]'::jsonb, array['emotion words', 'art', 'children']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('courage-medal-maker', 'Courage Medal Maker', 'kids'::resource_kind, 'The child designs a paper medal for a brave thing they did and decides who presents it.', 'Use it to help a child notice and celebrate small acts of courage.', array['Children']::text[], '25 minutes', 'Provide paper, string, stickers. The child names something that took courage, even if small. The parent presents the medal with a sentence about what they saw. Praise the effort rather than the result.', '[{"id": "f0", "type": "textarea", "label": "Draw my medal"}, {"id": "f1", "type": "textarea", "label": "The brave thing I did"}, {"id": "f2", "type": "textarea", "label": "Draw how it felt in my body when I was brave"}, {"id": "f3", "type": "textarea", "label": "Who gives me the medal and what they say"}]'::jsonb, array['courage', 'praise', 'strengths']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('brave-backpack-collage', 'Brave Backpack Collage', 'kids'::resource_kind, 'The child glues pictures onto a paper backpack showing what helps them feel brave.', 'Use it to help a child pick out the people, things and ideas that support them.', array['Children']::text[], '30 minutes', 'Cut a backpack shape and offer magazines or drawings. The child fills it with what helps: people, objects, words. The parent adds one thing too. Hang the backpack where the child will see it often.', '[{"id": "f0", "type": "textarea", "label": "Draw or glue what helps me feel brave"}, {"id": "f1", "type": "textarea", "label": "The person who helps me most"}, {"id": "f2", "type": "textarea", "label": "A word that makes me feel strong"}, {"id": "f3", "type": "textarea", "label": "What I would put in my backpack for a tough day"}]'::jsonb, array['coping skills', 'collage', 'support']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('kindness-garden-paper-flowers', 'Kindness Garden Paper Flowers', 'kids'::resource_kind, 'The child makes a paper flower for each kind act and plants it in a garden on the wall.', 'Use it to help a child see how small kind acts add up.', array['Children']::text[], '30 minutes', 'Make flowers from paper and craft sticks. Each flower records a kind thing the child did or received. The parent helps write the notes and adds some of their own. The garden grows over a few weeks.', '[{"id": "f0", "type": "textarea", "label": "Draw a flower for a kind thing I did"}, {"id": "f1", "type": "textarea", "label": "Draw a flower for a kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "Who I want to be kind to this week"}, {"id": "f3", "type": "textarea", "label": "How it feels to be kind"}]'::jsonb, array['kindness', 'craft', 'gratitude']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('calm-bottle-sensory-kit', 'Calm Bottle Sensory Kit', 'kids'::resource_kind, 'The child builds a sensory bottle with water and glitter and uses it as a calm-down tool.', 'Use it to give a child a visual, hands-on tool for slowing down.', array['Children']::text[], '30 minutes', 'Fill a clear bottle with warm water, glitter glue and glitter, and seal it. The child shakes it and breathes while the glitter settles. The parent keeps the bottle handy and offers it before big feelings, not as a punishment.', '[{"id": "f0", "type": "textarea", "label": "Draw my calm bottle"}, {"id": "f1", "type": "textarea", "label": "What the glitter looks like when it settles"}, {"id": "f2", "type": "textarea", "label": "Where I will keep my bottle"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will say when I need it"}]'::jsonb, array['calm down', 'sensory', 'self-regulation']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('skill-spinner-challenge', 'Skill Spinner Challenge', 'game'::resource_kind, 'A spinner game where each landing names a coping skill that the player acts out or describes.', 'Use it to turn practicing coping skills into something lively.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Make a spinner with six skills. Players take turns spinning, then demonstrate or describe the skill. Award a point for trying, not for doing it best. Debrief by asking which skills each player might use this week.', '[{"id": "f0", "type": "textarea", "label": "The skill my spin landed on"}, {"id": "f1", "type": "textarea", "label": "How I showed it"}, {"id": "f2", "type": "textarea", "label": "Which skill I would use on a tough day"}, {"id": "f3", "type": "textarea", "label": "What I learned from watching others"}]'::jsonb, array['coping skills', 'game', 'skills practice']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('strengths-object-scavenger-hunt', 'Strengths Object Scavenger Hunt', 'game'::resource_kind, 'Players search the room for objects that stand for personal strengths and explain their choices.', 'Use it to help players name strengths in a playful, active way.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Call out a strength and give players one minute to find an object that fits and tell why. Take turns calling. Debrief on strengths others noticed in them and one they want to use more.', '[{"id": "f0", "type": "textarea", "label": "The strength I chose and the object that stands for it"}, {"id": "f1", "type": "textarea", "label": "A strength someone noticed in me"}, {"id": "f2", "type": "textarea", "label": "A strength I want to use more"}, {"id": "f3", "type": "textarea", "label": "How I can use it this week"}]'::jsonb, array['strengths', 'game', 'identity']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('perspective-swap-story-chain', 'Perspective Swap Story Chain', 'game'::resource_kind, 'Players build a story one sentence at a time, switching to a new character''s view each turn.', 'Use it to practice seeing a situation from more than one side.', array['Teens', 'Groups']::text[], '35 minutes', 'Start with a short conflict scene. Each player adds a sentence from a different character''s view, going around twice. Debrief on how the story changed and where seeing another view felt easy or hard.', '[{"id": "f0", "type": "textarea", "label": "The scene we started with"}, {"id": "f1", "type": "textarea", "label": "How the story changed when we switched views"}, {"id": "f2", "type": "textarea", "label": "The view that was hardest to take"}, {"id": "f3", "type": "textarea", "label": "A real situation where I could try this"}]'::jsonb, array['perspective taking', 'storytelling', 'communication']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('boundary-traffic-light-game', 'Boundary Traffic Light Game', 'game'::resource_kind, 'A card game where players sort statements into green, yellow and red boundaries and say why.', 'Use it to practice recognizing and stating personal limits.', array['Teens', 'Groups']::text[], '35 minutes', 'Write short scenarios on cards. Players take turns drawing one, sorting it by traffic light color and explaining what they might say. Debrief on which limits felt hard to state and which words felt natural.', '[{"id": "f0", "type": "textarea", "label": "A scenario I sorted and why"}, {"id": "f1", "type": "textarea", "label": "Words I could use to state a limit"}, {"id": "f2", "type": "textarea", "label": "A limit that is hard for me to set"}, {"id": "f3", "type": "textarea", "label": "One boundary I will practice this week"}]'::jsonb, array['boundaries', 'assertiveness', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('problem-solving-dominoes', 'Problem-Solving Dominoes', 'game'::resource_kind, 'Players link dominoes from problem to option to consequence to plan as they work through a scenario.', 'Use it to practice breaking a problem into steps and choosing a plan.', array['Children', 'Teens', 'Groups']::text[], '35 minutes', 'Make cards for problem, options, outcomes and plan, and lay them like dominoes. Players take turns adding the next card. Debrief on which step felt easiest and where they got stuck.', '[{"id": "f0", "type": "textarea", "label": "The problem we worked on"}, {"id": "f1", "type": "textarea", "label": "The options we found"}, {"id": "f2", "type": "textarea", "label": "The plan we chose and why"}, {"id": "f3", "type": "textarea", "label": "A real problem I could try this on"}]'::jsonb, array['problem solving', 'game', 'planning']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('steady-ground-daily-gauge', 'Steady Ground Daily Gauge', 'worksheet'::resource_kind, 'A daily gauge for noticing how settled or activated a client feels and what helped them steady.', 'Use it to help a client track steadiness and the supports that work.', array['Adults']::text[], '5 minutes daily for two weeks', 'The client rates steadiness and notes one thing that helped, never the details of past events. Review the pattern together and let them lead on which supports to use more. If a gauge entry points to risk, address it in session.', '[{"id": "f0", "type": "textarea", "label": "Right now my steadiness is (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body today:"}, {"id": "f2", "type": "textarea", "label": "One thing that helped me feel steadier:"}, {"id": "f3", "type": "textarea", "label": "One thing I will do for myself tomorrow:"}]'::jsonb, array['PTSD and trauma', 'stabilization', 'window of tolerance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('heavy-day-pacing-skills-card', 'Heavy Day Pacing Skills Card', 'dbt'::resource_kind, 'A card of skills for slowing down on a heavy day, with a plan to stop and reset.', 'Use it to help a client pace themselves and choose stabilizing skills on hard days.', array['Adults']::text[], '25 minutes', 'Build the card in session from the client''s own skills: grounding, self-soothing, reaching out. Practice using it when calm. The card never asks for details of what happened; it is about pacing and safety now.', '[{"id": "f0", "type": "textarea", "label": "Signs that today is a heavy day:"}, {"id": "f1", "type": "textarea", "label": "Two skills that help me slow down:"}, {"id": "f2", "type": "textarea", "label": "A safe person I can contact:"}, {"id": "f3", "type": "textarea", "label": "What I will stop doing for the next hour:"}, {"id": "f4", "type": "textarea", "label": "If I ever feel unsafe, I can call or text 988."}]'::jsonb, array['PTSD and trauma', 'pacing', 'distress tolerance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('slow-rebuilding-values-compass', 'Slow Rebuilding Values Compass', 'act'::resource_kind, 'A compass page for choosing small values-based actions during a slow stretch of rebuilding.', 'Use it to help a client move toward what matters at a pace they set.', array['Adults']::text[], '25 minutes', 'Focus on the present and the future, not on past events. Ask which value they want to move toward and what a very small step looks like. They set the pace; stopping or slowing is a valid choice.', '[{"id": "f0", "type": "textarea", "label": "A value I want to move toward:"}, {"id": "f1", "type": "textarea", "label": "One very small step that fits it:"}, {"id": "f2", "type": "textarea", "label": "What helps me feel safe enough to try:"}, {"id": "f3", "type": "textarea", "label": "How I will know it is time to slow down:"}]'::jsonb, array['PTSD and trauma', 'values', 'pacing']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('my-safe-helpers-tree-drawing', 'My Safe Helpers Tree Drawing', 'kids'::resource_kind, 'The child draws a tree whose leaves are the people and places that help them feel safe.', 'Use it to help a child identify trusted people and safe places.', array['Children']::text[], '30 minutes', 'The child draws a tree and writes or dictates names on the leaves; the parent helps and adds their own. Do not ask about events. If a child discloses harm, follow your reporting duties and make sure the child is told they did the right thing.', '[{"id": "f0", "type": "textarea", "label": "Draw my safe helpers tree"}, {"id": "f1", "type": "textarea", "label": "The people I can tell when I feel scared"}, {"id": "f2", "type": "textarea", "label": "My safe places"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will do when I tell them"}]'::jsonb, array['PTSD and trauma', 'safe adults', 'safety']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('five-anchors-grounding-relay', 'Five Anchors Grounding Relay', 'game'::resource_kind, 'A team relay where players collect objects for each sense and share one calming thing about each.', 'Use it to practice grounding skills in a lively, low-pressure group.', array['Teens', 'Groups']::text[], '30 minutes', 'Set up five stations, one for each sense. Players take turns collecting an item and naming how it anchors them to the room. Let anyone pass. Debrief on which anchor was easiest and which each player will carry forward.', '[{"id": "f0", "type": "textarea", "label": "The sense I used and the item I chose"}, {"id": "f1", "type": "textarea", "label": "How it helped me feel here and now"}, {"id": "f2", "type": "textarea", "label": "The anchor I will keep using"}, {"id": "f3", "type": "textarea", "label": "What I noticed in the group"}]'::jsonb, array['PTSD and trauma', 'grounding', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('worry-or-problem-two-column-sort', 'Worry or Problem Two-Column Sort', 'worksheet'::resource_kind, 'A sheet that sorts today''s worries into problems to act on and ones to let sit.', 'Use it to help a client separate what they can do something about from what they cannot.', array['Adults', 'Teens']::text[], '20 minutes', 'List the week''s worries together, then sort. Problems get a small next action; the rest get a note on how to let them be. Expect many worries to sit in between; that is fine.', '[{"id": "f0", "type": "textarea", "label": "Worries on my mind this week:"}, {"id": "f1", "type": "textarea", "label": "Which ones I can act on:"}, {"id": "f2", "type": "textarea", "label": "One small step for each of those:"}, {"id": "f3", "type": "textarea", "label": "Which ones I cannot act on, and how I will let them sit:"}]'::jsonb, array['anxiety', 'worry', 'problem solving']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('not-knowing-small-steps-experiment-log', 'Not-Knowing Small Steps Experiment Log', 'cbt'::resource_kind, 'A log for taking small steps into not knowing and noting what happens.', 'Use it to help a client test whether they can handle uncertainty.', array['Adults']::text[], 'One week', 'Pick one small uncertain thing the client usually avoids or checks, agree on a step, and record predictions and outcomes. Treat each entry as data. Build up gradually and review with curiosity.', '[{"id": "f0", "type": "textarea", "label": "The uncertain situation I chose:"}, {"id": "f1", "type": "textarea", "label": "What I predicted would happen:"}, {"id": "f2", "type": "textarea", "label": "What I did:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}, {"id": "f4", "type": "textarea", "label": "What I learned about handling not knowing:"}]'::jsonb, array['anxiety', 'uncertainty', 'behavioral experiment']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('carrying-worry-up-the-hill-page', 'Carrying Worry Up the Hill Page', 'act'::resource_kind, 'A page based on the image of carrying worries up a hill while walking toward a value.', 'Use it to help a client keep moving toward what matters while worries come along.', array['Adults']::text[], '25 minutes', 'Have the client name the hill, which value it leads to, and what worries come along. The point is not to leave the worries behind but to keep climbing. Ask what they can do while carrying them.', '[{"id": "f0", "type": "textarea", "label": "The hill I want to climb (a value I care about):"}, {"id": "f1", "type": "textarea", "label": "The worries that come along:"}, {"id": "f2", "type": "textarea", "label": "What I can do next while I carry them:"}, {"id": "f3", "type": "textarea", "label": "Who could walk with me:"}]'::jsonb, array['anxiety', 'values', 'acceptance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('worry-cloud-drawing-and-release', 'Worry Cloud Drawing and Release', 'kids'::resource_kind, 'The child draws worries as clouds, then decides which ones to blow away and which to share with a grown-up.', 'Use it to help a child put worries into pictures and talk about them.', array['Children']::text[], '25 minutes', 'Draw clouds, one per worry, and use cotton balls to make some of them fluffy. The parent listens without fixing and thanks the child for sharing. Pick one cloud to talk through together.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry clouds"}, {"id": "f1", "type": "textarea", "label": "The biggest cloud and what it says"}, {"id": "f2", "type": "textarea", "label": "A cloud I can blow away for now"}, {"id": "f3", "type": "textarea", "label": "A cloud I want to share with my grown-up"}]'::jsonb, array['anxiety', 'worry', 'art']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('calm-breath-race-cards', 'Calm Breath Race Cards', 'game'::resource_kind, 'A card game where players draw calming breaths and move their game piece for completing them.', 'Use it to make practicing slow breathing a shared activity.', array['Children', 'Groups']::text[], '25 minutes', 'Make cards for belly breath, square breath, smell the flower and others. Players draw, do the breath and advance a space. The first to the finish line earns a cheer, but all finish. Debrief on which breath they liked.', '[{"id": "f0", "type": "textarea", "label": "The breath I liked best"}, {"id": "f1", "type": "textarea", "label": "How my body felt after"}, {"id": "f2", "type": "textarea", "label": "When I could use it"}, {"id": "f3", "type": "textarea", "label": "What I would teach someone else"}]'::jsonb, array['anxiety', 'breathing', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('low-energy-day-minimum-list', 'Low Energy Day Minimum List', 'worksheet'::resource_kind, 'A short list of the smallest things that still count on a very low energy day.', 'Use it to help a client set a floor for hard days without guilt.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the list with the client, keeping each item small enough to do on the worst day. Avoid framing it as a task list to fail. Ask which item matters most to them and how they will reward themselves for doing even one.', '[{"id": "f0", "type": "textarea", "label": "What I need to do to feel okay at the minimum:"}, {"id": "f1", "type": "textarea", "label": "One thing I can do for someone else, even tiny:"}, {"id": "f2", "type": "textarea", "label": "One thing I can do for myself:"}, {"id": "f3", "type": "textarea", "label": "How I will talk to myself on a low day:"}]'::jsonb, array['depression', 'energy', 'self-compassion']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('day-activity-and-mood-pairing-chart', 'Day Activity and Mood Pairing Chart', 'cbt'::resource_kind, 'A chart that links daily activities to mood so a client can see what lifts or lowers it.', 'Use it to help a client notice which activities go with better moods.', array['Adults', 'Teens']::text[], 'One week', 'The client records an activity and a mood rating, then reviews patterns with you. Look for small activities tied to higher moods. Stay curious; the data shows what helps for them, not what they should do.', '[{"id": "f0", "type": "textarea", "label": "The activity:"}, {"id": "f1", "type": "textarea", "label": "My mood before (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "My mood after (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I notice across the week:"}, {"id": "f4", "type": "textarea", "label": "One activity to add or try again:"}]'::jsonb, array['depression', 'behavioral activation', 'mood tracking']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('gentle-routine-anchors-card', 'Gentle Routine Anchors Card', 'dbt'::resource_kind, 'A card of four small daily anchors that give the day a shape when motivation is low.', 'Use it to help a client build a gentle routine around basic self-care.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose four anchors with the client, such as light, a meal, movement and contact with another person. Frame them as supports, not demands. Review which anchors held and which need to change.', '[{"id": "f0", "type": "textarea", "label": "My four anchors for the day:"}, {"id": "f1", "type": "textarea", "label": "When I will do each one:"}, {"id": "f2", "type": "textarea", "label": "What might get in the way:"}, {"id": "f3", "type": "textarea", "label": "How I will be kind to myself if I miss one:"}]'::jsonb, array['depression', 'routine', 'self-care']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('partner-support-plan-for-heavy-days', 'Partner Support Plan for Heavy Days', 'couples'::resource_kind, 'A conversation sheet for a couple to talk about how to support each other on heavy days.', 'Use it to help partners agree on how to ask for and offer support.', array['Couples']::text[], '40 minutes', 'Each partner says what helps and what does not, in plain words. Practice one request and one response in session. Check that the partner supporting does not become the only support; discuss other people.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me on a heavy day:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what helps me on a heavy day:"}, {"id": "f2", "type": "textarea", "label": "What each of us wishes the other would not do:"}, {"id": "f3", "type": "textarea", "label": "A signal we will use to ask for support:"}, {"id": "f4", "type": "textarea", "label": "Other people and supports we can add:"}]'::jsonb, array['depression', 'support', 'communication']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('sunshine-jar-of-good-moments', 'Sunshine Jar of Good Moments', 'kids'::resource_kind, 'The child fills a jar with paper sunbeams that name good moments from the day.', 'Use it to help a child notice and keep small good moments.', array['Children']::text[], '20 minutes', 'Cut yellow paper into rays. Each evening the child, with the parent, writes or draws one good moment on a ray and drops it in the jar. Read a few together at the end of the week.', '[{"id": "f0", "type": "textarea", "label": "Draw a good moment from today"}, {"id": "f1", "type": "textarea", "label": "What happened and who was there"}, {"id": "f2", "type": "textarea", "label": "A good moment I want to make again"}, {"id": "f3", "type": "textarea", "label": "Which ray I want to read tomorrow"}]'::jsonb, array['depression', 'gratitude', 'children']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('next-right-step-starter-sheet', 'Next Right Step Starter Sheet', 'worksheet'::resource_kind, 'A sheet that shrinks a stalled task to one next step and a two-minute start.', 'Use it to help a client start tasks that feel too big.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a stuck task and break it into the smallest first move. Add a cue and a two-minute timer. Do the first step in session if possible. Expect to rebuild the step if it was still too big.', '[{"id": "f0", "type": "textarea", "label": "The task I am stuck on:"}, {"id": "f1", "type": "textarea", "label": "The very first tiny step:"}, {"id": "f2", "type": "textarea", "label": "A cue that will remind me:"}, {"id": "f3", "type": "textarea", "label": "What I will use to start (timer, music, a person):"}]'::jsonb, array['ADHD', 'task initiation', 'small steps']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('time-blindness-estimate-and-check-log', 'Time Blindness Estimate and Check Log', 'cbt'::resource_kind, 'A log where a client guesses how long tasks take, then checks, to calibrate their sense of time.', 'Use it to help a client plan around how long things really take.', array['Adults', 'Teens']::text[], 'One week', 'The client writes an estimate, times the task and notes the gap. Look at which tasks run long and add buffers. Frame the gap as information, not failure.', '[{"id": "f0", "type": "textarea", "label": "The task:"}, {"id": "f1", "type": "textarea", "label": "How long I think it will take:"}, {"id": "f2", "type": "textarea", "label": "How long it took:"}, {"id": "f3", "type": "textarea", "label": "What took longer or shorter than I expected:"}, {"id": "f4", "type": "textarea", "label": "The buffer I will add next time:"}]'::jsonb, array['ADHD', 'time management', 'self-monitoring']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('values-over-distractions-focus-page', 'Values Over Distractions Focus Page', 'act'::resource_kind, 'A page for noticing what pulls attention away and choosing to return to what matters.', 'Use it to help a client come back to chosen tasks after drifting.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the value behind the task so the return has meaning. Have the client list their top distractions and practice a gentle, repeatable return. Drifting is normal; the skill is coming back.', '[{"id": "f0", "type": "textarea", "label": "What I am trying to focus on and why it matters:"}, {"id": "f1", "type": "textarea", "label": "My top distractions:"}, {"id": "f2", "type": "textarea", "label": "What I will say to myself when I notice I drifted:"}, {"id": "f3", "type": "textarea", "label": "One thing I will change in my space:"}]'::jsonb, array['ADHD', 'values', 'attention']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('shared-reminders-system-agreement', 'Shared Reminders System Agreement', 'couples'::resource_kind, 'A written agreement on how partners use reminders and prompts without nagging.', 'Use it to help a couple handle reminders in a way that does not feel like parenting.', array['Couples']::text[], '35 minutes', 'Both partners say what helps and what feels like nagging. Choose tools, such as shared lists or alarms, and agree on how to ask. Revisit the agreement after two weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: reminders that help me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: reminders that feel like nagging to me:"}, {"id": "f2", "type": "textarea", "label": "Tools we will use:"}, {"id": "f3", "type": "textarea", "label": "How we will ask for a reminder:"}, {"id": "f4", "type": "textarea", "label": "When we will review the system:"}]'::jsonb, array['ADHD', 'organization', 'communication']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('focus-sprint-timer-challenge', 'Focus Sprint Timer Challenge', 'game'::resource_kind, 'A game of short timed focus sprints with breaks, bonuses and a debrief on what helped.', 'Use it to make practicing focus in short bursts feel playful.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Set a timer for short sprints on a chosen task. Players earn points for starting on time and returning after drifting. Breaks are part of the game. Debrief on what made starting easier.', '[{"id": "f0", "type": "textarea", "label": "The task I chose for my sprint"}, {"id": "f1", "type": "textarea", "label": "How long I stayed on it"}, {"id": "f2", "type": "textarea", "label": "What helped me start and return"}, {"id": "f3", "type": "textarea", "label": "What I will try on my own this week"}]'::jsonb, array['ADHD', 'focus', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('high-risk-moments-map-for-substance-use', 'High-Risk Moments Map for Substance Use', 'worksheet'::resource_kind, 'A map of the times, places and feelings that bring up urges, with a plan for each.', 'Use it to help a client prepare for moments when urges are strongest.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to list the people, places, times and feelings that bring up urges. For each, build one plan. Keep language free of labels; the client is a person with urges, not a category. Review after a few weeks.', '[{"id": "f0", "type": "textarea", "label": "Times of day when urges are strongest:"}, {"id": "f1", "type": "textarea", "label": "Places or people linked with urges:"}, {"id": "f2", "type": "textarea", "label": "Feelings that come before an urge:"}, {"id": "f3", "type": "textarea", "label": "My plan for the riskiest moment:"}, {"id": "f4", "type": "textarea", "label": "Who I can call first:"}]'::jsonb, array['addiction', 'urges', 'relapse prevention']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('urge-thought-challenge-card', 'Urge Thought Challenge Card', 'cbt'::resource_kind, 'A card for catching thoughts that give urges permission and writing a steadier reply.', 'Use it to help a client respond to permission-giving thoughts about substance use.', array['Adults']::text[], '25 minutes', 'Identify thoughts like just this once and write a reply for each. Role-play reading the card in an urge. Do not argue with the thought for them; let the client choose words that sound like them.', '[{"id": "f0", "type": "textarea", "label": "A thought that gives an urge permission:"}, {"id": "f1", "type": "textarea", "label": "What happens if I act on it, short term and later:"}, {"id": "f2", "type": "textarea", "label": "A steadier reply:"}, {"id": "f3", "type": "textarea", "label": "What I will do instead:"}]'::jsonb, array['addiction', 'urges', 'cognitive restructuring']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('urge-interrupt-skills-ladder', 'Urge Interrupt Skills Ladder', 'dbt'::resource_kind, 'A ladder of skills for riding out an urge, from quick body resets to calling someone.', 'Use it to help a client climb through skills while an urge rises and falls.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the ladder with quick body skills at the bottom and connection at the top. Rehearse climbing it. Note that urges rise and fall; the ladder helps them wait it out. Ask what step they would start with.', '[{"id": "f0", "type": "textarea", "label": "Quick body skill I will start with:"}, {"id": "f1", "type": "textarea", "label": "A distraction I can do for ten minutes:"}, {"id": "f2", "type": "textarea", "label": "Someone I can reach out to:"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself while the urge passes:"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('meaning-beyond-substance-use-page', 'Meaning Beyond Substance Use Page', 'act'::resource_kind, 'A page for listing what matters in life and what the client wants more room for.', 'Use it to help a client connect recovery to their values.', array['Adults']::text[], '25 minutes', 'Ask what the client wants their life to be about and what substance use has crowded out. Keep tone free of shame. End with one small value-based action this week.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me in life:"}, {"id": "f1", "type": "textarea", "label": "What substance use has made less room for:"}, {"id": "f2", "type": "textarea", "label": "What I want more room for:"}, {"id": "f3", "type": "textarea", "label": "One action this week that fits my values:"}]'::jsonb, array['addiction', 'values', 'recovery']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('refusal-practice-role-play-cards', 'Refusal Practice Role-Play Cards', 'game'::resource_kind, 'Cards with offers and pressure lines for players to practice saying no, with a coach and an observer.', 'Use it to practice saying no to substance use in realistic scenarios.', array['Teens', 'Adults', 'Groups']::text[], '35 minutes', 'Write offers on cards. One player responds, one pushes, one observes. Rotate roles. Debrief on which responses felt strong and which words the player wants to use. Keep scenarios realistic, not frightening.', '[{"id": "f0", "type": "textarea", "label": "The offer I practiced saying no to"}, {"id": "f1", "type": "textarea", "label": "The words I used"}, {"id": "f2", "type": "textarea", "label": "What the observer saw"}, {"id": "f3", "type": "textarea", "label": "The line I will keep for real life"}]'::jsonb, array['addiction', 'refusal skills', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('anger-early-signals-body-map', 'Anger Early Signals Body Map', 'worksheet'::resource_kind, 'A body outline where a client marks where anger first shows up and what comes next.', 'Use it to help a client notice early signals before anger peaks.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to mark early, middle and peak signals in different colors. Explore the first signal; that is the best moment to step in. Link each to a small action.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anger first:"}, {"id": "f1", "type": "textarea", "label": "What happens in the middle:"}, {"id": "f2", "type": "textarea", "label": "What happens at the peak:"}, {"id": "f3", "type": "textarea", "label": "What I can do at the first signal:"}]'::jsonb, array['anger management', 'body signals', 'early warning']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('anger-thought-swap-page', 'Anger Thought Swap Page', 'cbt'::resource_kind, 'A page for catching thoughts that fuel anger and trying thoughts that leave room to choose.', 'Use it to help a client see how thoughts shape the intensity of anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a recent moment and write the hot thought. Ask what the person might have meant and what the client''s other options were. Not every swap will fit; the goal is to widen choices.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "The thought that made me angrier:"}, {"id": "f2", "type": "textarea", "label": "Another way to read it:"}, {"id": "f3", "type": "textarea", "label": "What I could do instead:"}]'::jsonb, array['anger management', 'anger', 'cognitive restructuring']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('pause-and-choose-skills-sheet', 'Pause and Choose Skills Sheet', 'dbt'::resource_kind, 'A sheet that pairs a pause skill with a choice for what to do when anger rises.', 'Use it to help a client use a pause skill before acting on anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one pause skill, such as stepping away or slow breathing, and one choice for after. Role-play it. Ask what would make them forget and how to remind themselves.', '[{"id": "f0", "type": "textarea", "label": "The pause skill I will use:"}, {"id": "f1", "type": "textarea", "label": "How I will remind myself:"}, {"id": "f2", "type": "textarea", "label": "What I will choose after the pause:"}, {"id": "f3", "type": "textarea", "label": "What I will say to the other person if needed:"}]'::jsonb, array['anger management', 'pause', 'distress tolerance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('volcano-calm-down-steps-poster', 'Volcano Calm-Down Steps Poster', 'kids'::resource_kind, 'The child draws a volcano with steps for what to do as feelings heat up.', 'Use it to give a child a visual map of anger and calming steps.', array['Children']::text[], '30 minutes', 'Draw a volcano with levels from calm to eruption. The child adds a step at each level, like counting or asking for space. The parent practices the steps with the child and hangs the poster at home.', '[{"id": "f0", "type": "textarea", "label": "Draw my volcano"}, {"id": "f1", "type": "textarea", "label": "What I feel at each level"}, {"id": "f2", "type": "textarea", "label": "The steps I will do"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will say to help"}]'::jsonb, array['anger management', 'calm down', 'art']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('respond-not-react-scenario-cards', 'Respond Not React Scenario Cards', 'game'::resource_kind, 'Cards with everyday frustrations for players to answer with a calm response, taking turns.', 'Use it to practice calm choices in frustrating moments.', array['Teens', 'Groups']::text[], '30 minutes', 'Draw a scenario, act out a reactive response, then a calm one. Others guess the difference. Debrief on what helps move from reaction to response.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "My calm response"}, {"id": "f2", "type": "textarea", "label": "What made it hard"}, {"id": "f3", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['anger management', 'role play', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('ritual-delay-timer-sheet', 'Ritual Delay Timer Sheet', 'worksheet'::resource_kind, 'A sheet for noting an urge to do a ritual and trying a short, planned delay.', 'Use it to help a client practice waiting before a ritual, at a pace they and you choose.', array['Adults', 'Teens']::text[], 'One week', 'Agree on a delay that is challenging but doable, in session. The client logs the urge, the delay and what happened. Increase gradually. The pace and goals are the clinician''s judgment with the client.', '[{"id": "f0", "type": "textarea", "label": "The urge or ritual:"}, {"id": "f1", "type": "textarea", "label": "How long I delayed:"}, {"id": "f2", "type": "textarea", "label": "What I felt while waiting:"}, {"id": "f3", "type": "textarea", "label": "What happened after:"}]'::jsonb, array['OCD', 'rituals', 'response delay']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('uncertainty-sentence-practice-page', 'Uncertainty Sentence Practice Page', 'cbt'::resource_kind, 'A page for writing and rehearsing sentences that accept some doubt without a check.', 'Use it to help a client practice responding to doubt without reassurance.', array['Adults']::text[], '25 minutes', 'Draft sentences like Maybe, maybe not with the client. Practice saying them in session. They are not meant to calm the client down; they are meant to let doubt be present.', '[{"id": "f0", "type": "textarea", "label": "A doubt that shows up:"}, {"id": "f1", "type": "textarea", "label": "A sentence that lets it be there:"}, {"id": "f2", "type": "textarea", "label": "What I notice when I say it:"}, {"id": "f3", "type": "textarea", "label": "What I do next:"}]'::jsonb, array['OCD', 'uncertainty', 'intrusive thoughts']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('doubt-along-for-the-ride-page', 'Doubt Along for the Ride Page', 'act'::resource_kind, 'A page that pictures doubt as a passenger while the client drives toward a value.', 'Use it to help a client choose valued action when doubt is loud.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the doubt and the value together. Ask what the client wants to do with the next hour. Coming along does not mean agreeing.', '[{"id": "f0", "type": "textarea", "label": "The doubt that rides along:"}, {"id": "f1", "type": "textarea", "label": "The value I am driving toward:"}, {"id": "f2", "type": "textarea", "label": "What I will do in the next hour:"}, {"id": "f3", "type": "textarea", "label": "What I say to the doubt:"}]'::jsonb, array['OCD', 'defusion', 'values']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('worry-boss-talk-back-comic', 'Worry Boss Talk-Back Comic', 'kids'::resource_kind, 'The child draws a comic of a bossy worry and the brave things the child says back.', 'Use it to help a child name and talk back to bossy worries.', array['Children']::text[], '30 minutes', 'The child draws panels where the worry boss makes demands and the child answers. The parent learns not to join rituals or give reassurance on cue, and instead cheers the child''s talk-back. Keep it silly.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry boss"}, {"id": "f1", "type": "textarea", "label": "What the boss tells me to do"}, {"id": "f2", "type": "textarea", "label": "What I say back"}, {"id": "f3", "type": "textarea", "label": "What my grown-up does to help"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('doubt-dice-not-knowing-game', 'Doubt Dice Not Knowing Game', 'game'::resource_kind, 'A dice game of small uncertain tasks where players practice moving on without checking.', 'Use it to practice tolerating doubt in a light, playful way.', array['Teens', 'Groups']::text[], '30 minutes', 'Roll a die, then do a small task without redoing it, such as placing a card and leaving it. Others cheer. Keep tasks mild. Debrief on how doubt felt and rose or fell.', '[{"id": "f0", "type": "textarea", "label": "The task I did"}, {"id": "f1", "type": "textarea", "label": "How doubt felt"}, {"id": "f2", "type": "textarea", "label": "What I did instead of checking"}, {"id": "f3", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['OCD', 'uncertainty', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('panic-wave-notes-page', 'Panic Wave Notes Page', 'worksheet'::resource_kind, 'A page for jotting down the shape of a panic wave: start, peak and how it passed.', 'Use it to help a client see that panic rises and passes.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client note what they felt, how long the peak lasted and what they did. Over time they see a wave. If symptoms are new or unexplained, the clinician should consider medical review.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I felt first:"}, {"id": "f1", "type": "textarea", "label": "The peak of the wave:"}, {"id": "f2", "type": "textarea", "label": "How long until it eased:"}, {"id": "f3", "type": "textarea", "label": "What helped:"}]'::jsonb, array['panic attacks', 'body sensations', 'panic']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('body-sensation-second-look-cards', 'Body Sensation Second-Look Cards', 'cbt'::resource_kind, 'Cards pairing a body sensation with a fear thought and a more balanced explanation.', 'Use it to help a client practice a calmer read of body sensations.', array['Adults', 'Teens']::text[], '25 minutes', 'Write a sensation on one side and the fear thought on the other, then a balanced reading on the back. Practice flipping the cards. Check any physical concerns with a medical provider.', '[{"id": "f0", "type": "textarea", "label": "A sensation I notice:"}, {"id": "f1", "type": "textarea", "label": "The fear thought that goes with it:"}, {"id": "f2", "type": "textarea", "label": "A more balanced explanation:"}, {"id": "f3", "type": "textarea", "label": "What I will do when it shows up:"}]'::jsonb, array['panic attacks', 'interoceptive', 'thoughts']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('cold-water-reset-plan-card', 'Cold Water Reset Plan Card', 'dbt'::resource_kind, 'A card for using cold water or a cold pack to bring down intensity during a surge.', 'Use it to give a client a quick physical reset for peak moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Review safe use of cold water in session and check for health concerns first. Rehearse once. The client keeps the card where it is handy.', '[{"id": "f0", "type": "textarea", "label": "Where I will keep cold water or a cold pack:"}, {"id": "f1", "type": "textarea", "label": "Signs I need a reset:"}, {"id": "f2", "type": "textarea", "label": "The steps I will follow:"}, {"id": "f3", "type": "textarea", "label": "What I will do after:"}]'::jsonb, array['panic attacks', 'TIPP', 'distress tolerance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('slow-breath-pinwheel-build', 'Slow Breath Pinwheel Build', 'kids'::resource_kind, 'The child makes a pinwheel and uses slow breaths to make it spin.', 'Use it to give a child a playful way to practice slow breathing.', array['Children']::text[], '25 minutes', 'Build a pinwheel from paper and a pencil. The child breathes out slowly to spin it. The parent practices alongside and cues it when the child feels shaky. Decorate it together.', '[{"id": "f0", "type": "textarea", "label": "Draw my pinwheel"}, {"id": "f1", "type": "textarea", "label": "How my body feels when I breathe slowly"}, {"id": "f2", "type": "textarea", "label": "When I could use it"}, {"id": "f3", "type": "textarea", "label": "What my grown-up does with me"}]'::jsonb, array['panic attacks', 'breathing', 'craft']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('body-alarm-detective-game', 'Body Alarm Detective Game', 'game'::resource_kind, 'Players act as detectives investigating a false alarm in the body and report their findings.', 'Use it to explain that body alarms can sound without danger.', array['Teens', 'Groups']::text[], '30 minutes', 'Players pull a clue card, such as a racing heart, and decide as detectives whether the alarm needs action. Take turns. Debrief on how it feels to think like a detective during a surge.', '[{"id": "f0", "type": "textarea", "label": "The clue I drew"}, {"id": "f1", "type": "textarea", "label": "What I figured out"}, {"id": "f2", "type": "textarea", "label": "What a detective would do"}, {"id": "f3", "type": "textarea", "label": "How I can use this next time"}]'::jsonb, array['panic attacks', 'psychoeducation', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('family-weekly-rhythm-chart', 'Family Weekly Rhythm Chart', 'worksheet'::resource_kind, 'A weekly chart where a family maps predictable anchor points for mornings, meals and bedtimes.', 'Use it to help parents build a steady rhythm the whole family can follow.', array['Adults']::text[], '30 minutes', 'Have the parent fill in the anchors that already work, then add one new one. Aim for predictable, not rigid. Review after a week and adjust together.', '[{"id": "f0", "type": "textarea", "label": "Anchors in our week that already work:"}, {"id": "f1", "type": "textarea", "label": "The part of the day that is hardest:"}, {"id": "f2", "type": "textarea", "label": "One new anchor I will try:"}, {"id": "f3", "type": "textarea", "label": "How I will tell the family about it:"}]'::jsonb, array['parenting', 'routines', 'consistency']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('parent-thought-check-before-reacting', 'Parent Thought Check Before Reacting', 'cbt'::resource_kind, 'A page for catching a quick thought about a child''s behavior before responding.', 'Use it to help parents notice the thought behind their reaction.', array['Adults']::text[], '25 minutes', 'Take a recent tough moment and name the thought, such as they are doing it on purpose. Offer other readings. The goal is more choice in the moment, not blame.', '[{"id": "f0", "type": "textarea", "label": "What my child did:"}, {"id": "f1", "type": "textarea", "label": "The thought I had:"}, {"id": "f2", "type": "textarea", "label": "Other ways to read what happened:"}, {"id": "f3", "type": "textarea", "label": "What I would like to do next time:"}]'::jsonb, array['parenting', 'thoughts', 'parent coaching']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('parent-pause-skills-card', 'Parent Pause Skills Card', 'dbt'::resource_kind, 'A card of skills for pausing and settling before responding to a child.', 'Use it to help parents pause and choose a response.', array['Adults']::text[], '20 minutes', 'Choose two pause skills the parent can use in seconds. Rehearse in session. Include a repair line for when things go sideways.', '[{"id": "f0", "type": "textarea", "label": "Signs I am getting heated:"}, {"id": "f1", "type": "textarea", "label": "My pause skills:"}, {"id": "f2", "type": "textarea", "label": "What I will do after the pause:"}, {"id": "f3", "type": "textarea", "label": "A repair line I can say to my child:"}]'::jsonb, array['parenting', 'pause', 'self-regulation']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('co-parenting-weekly-handoff-sheet', 'Co-Parenting Weekly Handoff Sheet', 'couples'::resource_kind, 'A sheet for co-parents to share the week''s schedule, needs and open questions.', 'Use it to help co-parents coordinate smoothly.', array['Couples']::text[], '30 minutes', 'Both parents fill in their half, then talk. Keep the focus on the children and the logistics. If tension is high, use written exchange first.', '[{"id": "f0", "type": "textarea", "label": "Parent A: what I need to share about the week:"}, {"id": "f1", "type": "textarea", "label": "Parent B: what I need to share about the week:"}, {"id": "f2", "type": "textarea", "label": "Decisions we need to make:"}, {"id": "f3", "type": "textarea", "label": "How we will communicate this week:"}]'::jsonb, array['parenting', 'co-parenting', 'planning']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('notice-the-good-family-card-game', 'Notice the Good Family Card Game', 'game'::resource_kind, 'A family game where members collect cards for noticing good behavior in each other.', 'Use it to build a habit of noticing and praising helpful behavior.', array['Children', 'Adults']::text[], '20 minutes', 'Everyone gets a stack of cards. When someone does something helpful, the noticer writes it on a card. Count and share at dinner. Debrief on how it felt to be noticed.', '[{"id": "f0", "type": "textarea", "label": "A card I gave"}, {"id": "f1", "type": "textarea", "label": "A card I got"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "What we want more of"}]'::jsonb, array['parenting', 'praise', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('protected-rest-blocks-plan-for-new-parents', 'Protected Rest Blocks Plan for New Parents', 'worksheet'::resource_kind, 'A plan for how new parents protect blocks of sleep, with who covers which shifts.', 'Use it to help new parents guard their rest as much as they can.', array['Adults', 'Couples']::text[], '30 minutes', 'Map the 24 hours and place at least one protected block for each parent. Include backup help. If low mood or anxiety feels beyond normal adjustment, consider your own judgment and referral.', '[{"id": "f0", "type": "textarea", "label": "My best block of sleep and who covers it:"}, {"id": "f1", "type": "textarea", "label": "What helps me fall asleep:"}, {"id": "f2", "type": "textarea", "label": "Who can help for an hour:"}, {"id": "f3", "type": "textarea", "label": "What I will let go of this week:"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'new parents']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-thought-page', 'Good Enough Parent Thought Page', 'cbt'::resource_kind, 'A page that sets perfect-parent thoughts beside good-enough ones.', 'Use it to help new parents lower impossible standards.', array['Adults']::text[], '25 minutes', 'List the thoughts the parent has about how they should be doing it. Write good-enough replies. Ask who set the standard. Keep tone gentle.', '[{"id": "f0", "type": "textarea", "label": "A perfect-parent thought:"}, {"id": "f1", "type": "textarea", "label": "Where I learned it:"}, {"id": "f2", "type": "textarea", "label": "A good-enough reply:"}, {"id": "f3", "type": "textarea", "label": "What I did well today:"}]'::jsonb, array['perinatal and postpartum', 'self-criticism', 'perfectionism']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('small-moments-with-baby-savoring-log', 'Small Moments With Baby Savoring Log', 'act'::resource_kind, 'A log for noticing and savoring small moments with the baby, however brief.', 'Use it to help parents notice moments of connection.', array['Adults']::text[], 'One week', 'Ask for one moment a day, however small, and what the parent noticed. Hard feelings are welcome alongside. Don''t push joy.', '[{"id": "f0", "type": "textarea", "label": "Today''s moment:"}, {"id": "f1", "type": "textarea", "label": "What I noticed with my senses:"}, {"id": "f2", "type": "textarea", "label": "What I felt, including hard feelings:"}, {"id": "f3", "type": "textarea", "label": "What I want to remember:"}]'::jsonb, array['perinatal and postpartum', 'savoring', 'present moment']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('handing-off-baby-care-talk-sheet', 'Handing Off Baby Care Talk Sheet', 'couples'::resource_kind, 'A sheet for partners to talk through how to share baby care and ask for help.', 'Use it to help partners divide care in a way both can sustain.', array['Couples']::text[], '35 minutes', 'Each partner lists what they carry and what they need. Agree on a swap of tasks and a way to ask. Plan a short time for the couple.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I am carrying now:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I am carrying now:"}, {"id": "f2", "type": "textarea", "label": "What each of us needs:"}, {"id": "f3", "type": "textarea", "label": "A task we will swap:"}, {"id": "f4", "type": "textarea", "label": "A moment for us as a couple:"}]'::jsonb, array['perinatal and postpartum', 'teamwork', 'partners']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('big-sibling-welcome-book', 'Big Sibling Welcome Book', 'kids'::resource_kind, 'The child draws a welcome book for a new baby and tells what a big sibling can do.', 'Use it to help an older child adjust to a new baby.', array['Children']::text[], '30 minutes', 'The child makes a small book with drawings. The parent writes down what the child says, including mixed feelings. Plan special time with the older child.', '[{"id": "f0", "type": "textarea", "label": "Draw the new baby"}, {"id": "f1", "type": "textarea", "label": "What I can teach the baby"}, {"id": "f2", "type": "textarea", "label": "Something that feels hard"}, {"id": "f3", "type": "textarea", "label": "Special time I want with my grown-up"}]'::jsonb, array['perinatal and postpartum', 'siblings', 'sibling adjustment']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('strengths-evidence-wall-page', 'Strengths Evidence Wall Page', 'worksheet'::resource_kind, 'A page where a client stacks evidence for each of their strengths, brick by brick.', 'Use it to help a client build a record of what they do well.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client name a strength and give two real examples. If they dismiss them, ask what a friend would say. Display or revisit the page.', '[{"id": "f0", "type": "textarea", "label": "A strength I have:"}, {"id": "f1", "type": "textarea", "label": "Two times I showed it:"}, {"id": "f2", "type": "textarea", "label": "Who has seen it in me:"}, {"id": "f3", "type": "textarea", "label": "How I can use it this week:"}]'::jsonb, array['self-esteem', 'strengths', 'evidence']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('self-rating-replacement-page', 'Self-Rating Replacement Page', 'cbt'::resource_kind, 'A page for swapping global self-ratings for specific, fair descriptions.', 'Use it to help a client move from I am bad at everything to what actually happened.', array['Adults', 'Teens']::text[], '25 minutes', 'Capture the global label, then write specifics: what went well, what did not, what to try. Work for accuracy, not hype.', '[{"id": "f0", "type": "textarea", "label": "The global thing I say about myself:"}, {"id": "f1", "type": "textarea", "label": "What actually happened:"}, {"id": "f2", "type": "textarea", "label": "What I did well and what I would change:"}, {"id": "f3", "type": "textarea", "label": "A fair way to describe me:"}]'::jsonb, array['self-esteem', 'self-talk', 'cognitive restructuring']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('worth-without-proving-page', 'Worth Without Proving Page', 'act'::resource_kind, 'A page for noticing the urge to prove worth and choosing actions for values instead.', 'Use it to help a client act from values, not from the need to prove.', array['Adults']::text[], '25 minutes', 'Name where the client feels they must prove themselves. Contrast a proving action with a values action. Ask what changes in their body.', '[{"id": "f0", "type": "textarea", "label": "Where I feel I must prove myself:"}, {"id": "f1", "type": "textarea", "label": "What I do when I feel that:"}, {"id": "f2", "type": "textarea", "label": "What I would do if I acted on values:"}, {"id": "f3", "type": "textarea", "label": "One small values action:"}]'::jsonb, array['self-esteem', 'values', 'self-worth']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('treasure-chest-of-me-drawing', 'Treasure Chest of Me Drawing', 'kids'::resource_kind, 'The child draws a treasure chest and fills it with things that make them who they are.', 'Use it to help a child name what is special about them.', array['Children']::text[], '25 minutes', 'The child draws a chest and fills it with jewels labeled with things they are good at or like. The parent adds a jewel of their own, about what they love in the child.', '[{"id": "f0", "type": "textarea", "label": "Draw my treasure chest"}, {"id": "f1", "type": "textarea", "label": "The jewels inside"}, {"id": "f2", "type": "textarea", "label": "A jewel my grown-up adds"}, {"id": "f3", "type": "textarea", "label": "Where I will put it"}]'::jsonb, array['self-esteem', 'strengths', 'children']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('compliment-pass-circle-game', 'Compliment Pass Circle Game', 'game'::resource_kind, 'Players pass an object and give a sincere compliment about a skill or quality.', 'Use it to practice giving and receiving kind words.', array['Teens', 'Groups']::text[], '25 minutes', 'Pass an object around. The holder gives a specific compliment to someone. Receivers say thank you only. Debrief on how it felt to receive.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "A compliment I received"}, {"id": "f2", "type": "textarea", "label": "How it felt to receive"}, {"id": "f3", "type": "textarea", "label": "How I can accept kind words"}]'::jsonb, array['self-esteem', 'kindness', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('social-event-before-and-after-notes', 'Social Event Before and After Notes', 'worksheet'::resource_kind, 'A pair of notes for before and after a social event, to compare predictions with what happened.', 'Use it to help a client see how events go compared with their worries.', array['Adults', 'Teens']::text[], '20 minutes', 'Before: prediction and a small goal. After: what happened, what went fine. Watch for harsh post-event review; ask what a friend would notice.', '[{"id": "f0", "type": "textarea", "label": "What I expect to happen:"}, {"id": "f1", "type": "textarea", "label": "My small goal:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What went okay:"}]'::jsonb, array['social anxiety', 'post-event processing', 'prediction']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('safety-behavior-drop-trial-log', 'Safety Behavior Drop Trial Log', 'cbt'::resource_kind, 'A log for trying a social situation with one safety behavior dropped and noting results.', 'Use it to help a client learn from dropping a small safety behavior.', array['Adults', 'Teens']::text[], 'One week', 'Pick one behavior, like rehearsing lines, and agree to drop it once. Record prediction and result. Keep steps small.', '[{"id": "f0", "type": "textarea", "label": "The safety behavior I usually use:"}, {"id": "f1", "type": "textarea", "label": "What I predicted if I dropped it:"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['social anxiety', 'safety behaviors', 'behavioral experiment']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('nerves-along-for-the-social-step-page', 'Nerves Along for the Social Step Page', 'act'::resource_kind, 'A page that links a social value, like friendship, to a small step despite nerves.', 'Use it to help a client take a social step with nerves along.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the value and a small step. Practice making room for nerves. A step is successful if the client takes it, however it goes.', '[{"id": "f0", "type": "textarea", "label": "A relationship I value:"}, {"id": "f1", "type": "textarea", "label": "A small step toward it:"}, {"id": "f2", "type": "textarea", "label": "The nerves I expect:"}, {"id": "f3", "type": "textarea", "label": "How I will make room for them:"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('hello-practice-puppet-show', 'Hello Practice Puppet Show', 'kids'::resource_kind, 'The child and parent use puppets to practice saying hello, joining in and asking a friend to play.', 'Use it to help a child practice social steps in a playful way.', array['Children']::text[], '30 minutes', 'Use socks or paper puppets. Act out greeting someone, asking to join, and handling a no. The parent plays the friend first, then swaps roles. Praise trying.', '[{"id": "f0", "type": "textarea", "label": "Draw my puppet"}, {"id": "f1", "type": "textarea", "label": "What my puppet says to say hello"}, {"id": "f2", "type": "textarea", "label": "What my puppet does if someone says no"}, {"id": "f3", "type": "textarea", "label": "Who I will say hello to"}]'::jsonb, array['social anxiety', 'social skills', 'play']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('small-talk-topic-jar-game', 'Small Talk Topic Jar Game', 'game'::resource_kind, 'Players draw a topic from a jar and chat about it for one minute with a partner.', 'Use it to practice low-stakes conversation.', array['Teens', 'Groups']::text[], '30 minutes', 'Fill a jar with easy topics. Pairs draw, chat for one minute, then swap. Debrief on what was easiest and what they noticed about nerves.', '[{"id": "f0", "type": "textarea", "label": "The topic I drew"}, {"id": "f1", "type": "textarea", "label": "How the chat went"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f3", "type": "textarea", "label": "One question I can use in real life"}]'::jsonb, array['social anxiety', 'small talk', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('hard-dates-calendar-and-care-plan', 'Hard Dates Calendar and Care Plan', 'worksheet'::resource_kind, 'A calendar of hard dates in the year with a care plan for each.', 'Use it to help a client prepare for dates that carry grief.', array['Adults']::text[], '30 minutes', 'List birthdays, anniversaries and holidays. For each, write one way to care for themselves and one way to honor the person. Grief varies; no plan is right or wrong.', '[{"id": "f0", "type": "textarea", "label": "Dates that are hard for me:"}, {"id": "f1", "type": "textarea", "label": "How I want to honor my person that day:"}, {"id": "f2", "type": "textarea", "label": "How I will care for myself:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell:"}]'::jsonb, array['grief and loss', 'anniversaries', 'planning']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('should-thoughts-in-grief-page', 'Should Thoughts in Grief Page', 'cbt'::resource_kind, 'A page for looking at should and if only thoughts that come with loss.', 'Use it to help a client meet self-blame thoughts with fairness.', array['Adults']::text[], '25 minutes', 'Collect the shoulds. Ask what the client knew at the time. Write a kinder reply. Do not rush to remove guilt; make room for it.', '[{"id": "f0", "type": "textarea", "label": "A should or if only I have:"}, {"id": "f1", "type": "textarea", "label": "What I knew then:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought:"}]'::jsonb, array['grief and loss', 'guilt', 'self-blame']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('holding-love-and-loss-side-by-side-page', 'Holding Love and Loss Side by Side Page', 'act'::resource_kind, 'A page for holding love and loss at once and choosing one way to carry them.', 'Use it to help a client carry grief while moving toward what matters.', array['Adults']::text[], '25 minutes', 'Ask what the client loved and what they miss. Name a way to carry that love forward. Sadness stays welcome.', '[{"id": "f0", "type": "textarea", "label": "What I loved about my person:"}, {"id": "f1", "type": "textarea", "label": "What I miss most:"}, {"id": "f2", "type": "textarea", "label": "A way I can carry them with me:"}, {"id": "f3", "type": "textarea", "label": "What I want to do next:"}]'::jsonb, array['grief and loss', 'continuing bonds', 'values']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('painted-memory-stones-garden', 'Painted Memory Stones Garden', 'kids'::resource_kind, 'The child paints rocks with memories of someone they miss and sets them in a small garden.', 'Use it to give a child a hands-on way to remember.', array['Children']::text[], '30 minutes', 'Paint rocks with colors and symbols. The parent shares a memory for a rock too. Let the child decide where it goes and when to visit.', '[{"id": "f0", "type": "textarea", "label": "Draw a memory rock"}, {"id": "f1", "type": "textarea", "label": "The memory it holds"}, {"id": "f2", "type": "textarea", "label": "How I feel about them today"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to"}]'::jsonb, array['grief and loss', 'remembrance', 'craft']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('grieving-differently-together-talk-sheet', 'Grieving Differently Together Talk Sheet', 'couples'::resource_kind, 'A sheet for partners to talk about how each grieves and what they need.', 'Use it to help partners understand different ways of grieving.', array['Couples']::text[], '40 minutes', 'Each partner describes how they grieve and what they need. Normalize different paces. Plan a moment together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve:"}, {"id": "f2", "type": "textarea", "label": "What each of us needs:"}, {"id": "f3", "type": "textarea", "label": "A moment for us together:"}]'::jsonb, array['grief and loss', 'couples', 'understanding']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('relationship-patterns-timeline-page', 'Relationship Patterns Timeline Page', 'worksheet'::resource_kind, 'A timeline of past relationships to look for patterns in what helped and what repeated.', 'Use it to help a client spot patterns across relationships.', array['Adults']::text[], '35 minutes', 'Keep the focus on patterns rather than blame. Ask what they want to carry forward and change. Stay with the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "Relationships I want to look at:"}, {"id": "f1", "type": "textarea", "label": "What helped in them:"}, {"id": "f2", "type": "textarea", "label": "What repeated:"}, {"id": "f3", "type": "textarea", "label": "What I want to do differently:"}]'::jsonb, array['relationship issues', 'patterns', 'history']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('assumption-versus-fact-sorting-page', 'Assumption Versus Fact Sorting Page', 'cbt'::resource_kind, 'A page for sorting what a client knows from what they assume about a partner''s behavior.', 'Use it to help a client check assumptions before reacting.', array['Adults']::text[], '25 minutes', 'List what happened, then sort statements into facts and assumptions. Plan a question to check an assumption.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "What I know for sure:"}, {"id": "f2", "type": "textarea", "label": "What I am assuming:"}, {"id": "f3", "type": "textarea", "label": "A question I can ask:"}]'::jsonb, array['relationship issues', 'assumptions', 'communication']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('ask-without-demanding-script-builder', 'Ask Without Demanding Script Builder', 'dbt'::resource_kind, 'A builder for writing a request that is clear and respectful of the other person''s choice.', 'Use it to help a client practice asking for what they want.', array['Adults', 'Teens']::text[], '30 minutes', 'Write a clear request using the situation, the want and the reason. Role-play. Include a reply for a no.', '[{"id": "f0", "type": "textarea", "label": "What I want to ask for:"}, {"id": "f1", "type": "textarea", "label": "The words I will use:"}, {"id": "f2", "type": "textarea", "label": "What I will say if the answer is no:"}, {"id": "f3", "type": "textarea", "label": "How I will take care of myself after:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('repair-attempt-practice-cards', 'Repair Attempt Practice Cards', 'couples'::resource_kind, 'Cards with repair phrases for couples to practice using during a disagreement.', 'Use it to help a couple practice repair before they need it.', array['Couples']::text[], '30 minutes', 'Write phrases like Can we start over. Each partner picks cards they would accept and practices offering and receiving. Debrief on what works.', '[{"id": "f0", "type": "textarea", "label": "Partner A: repair phrases I would welcome:"}, {"id": "f1", "type": "textarea", "label": "Partner B: repair phrases I would welcome:"}, {"id": "f2", "type": "textarea", "label": "One I will try:"}, {"id": "f3", "type": "textarea", "label": "How we will accept an attempt:"}]'::jsonb, array['relationship issues', 'repair', 'conflict']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('two-truths-understanding-game', 'Two Truths Understanding Game', 'game'::resource_kind, 'Partners or group members share two sides of a situation and listen to understand.', 'Use it to practice holding two views at once.', array['Couples', 'Groups']::text[], '30 minutes', 'Take turns describing a situation from two angles. Listener reflects back. No fixing. Debrief on what helped understanding.', '[{"id": "f0", "type": "textarea", "label": "The situation I described"}, {"id": "f1", "type": "textarea", "label": "The two sides"}, {"id": "f2", "type": "textarea", "label": "What I heard"}, {"id": "f3", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['relationship issues', 'perspective taking', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('safe-support-and-boundaries-page', 'Safe Support and Boundaries Page', 'worksheet'::resource_kind, 'A page for listing safe people, safe places and boundaries a client wants in place now.', 'Use it to help a client strengthen present-day safety and support.', array['Adults', 'Teens']::text[], '30 minutes', 'Focus on today: who is safe, where is safe, which boundaries matter. Never ask for details of what happened. Complete it in session. The client sets the pace and can skip any line.', '[{"id": "f0", "type": "textarea", "label": "People I feel safe with:"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe:"}, {"id": "f2", "type": "textarea", "label": "A boundary I want in place now:"}, {"id": "f3", "type": "textarea", "label": "Who I can contact if I need support:"}, {"id": "f4", "type": "textarea", "label": "If I ever feel unsafe, I can call or text 988."}]'::jsonb, array['sexual abuse', 'safety', 'boundaries']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('coping-plan-for-reminders-without-details', 'Coping Plan for Reminders Without Details', 'dbt'::resource_kind, 'A plan for what to do when something reminds a client of harm, without recounting what happened.', 'Use it to help a client have steady skills ready for reminders.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the plan on present-day skills: grounding, naming the here and now, reaching out. The plan never asks for stories. Rehearse in session and stop if distress rises.', '[{"id": "f0", "type": "textarea", "label": "Things that can remind me (just a word or two):"}, {"id": "f1", "type": "textarea", "label": "How I notice it in my body:"}, {"id": "f2", "type": "textarea", "label": "Grounding skills I will use:"}, {"id": "f3", "type": "textarea", "label": "Who I can contact:"}]'::jsonb, array['sexual abuse', 'grounding', 'stabilization']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('values-and-safety-anchors-for-today', 'Values and Safety Anchors for Today', 'act'::resource_kind, 'A page for choosing a value and a safety anchor to guide the day.', 'Use it to help a client choose small values-based steps with safety in mind.', array['Adults']::text[], '25 minutes', 'Choose one value and one thing that makes the day feel safer. Keep it present-focused; no recounting. The client may pause at any time.', '[{"id": "f0", "type": "textarea", "label": "A value I want to guide me today:"}, {"id": "f1", "type": "textarea", "label": "Something that helps me feel safer:"}, {"id": "f2", "type": "textarea", "label": "One small step:"}, {"id": "f3", "type": "textarea", "label": "How I will pace myself:"}]'::jsonb, array['sexual abuse', 'values', 'pacing']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('trusted-adults-hand-map', 'Trusted Adults Hand Map', 'kids'::resource_kind, 'The child traces a hand and writes a trusted adult on each finger.', 'Use it to help a child identify the adults they can tell if something is wrong.', array['Children']::text[], '25 minutes', 'The child traces a hand and names five trusted adults. The parent confirms they will listen. Remind yourself of your reporting duties if a child discloses; never ask for details, and tell the child they did the right thing by telling.', '[{"id": "f0", "type": "textarea", "label": "Draw my hand and the adults I trust"}, {"id": "f1", "type": "textarea", "label": "What I can tell them"}, {"id": "f2", "type": "textarea", "label": "How I will ask for help"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will do"}]'::jsonb, array['sexual abuse', 'safe adults', 'body safety']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('safe-spaces-sorting-game', 'Safe Spaces Sorting Game', 'game'::resource_kind, 'Players sort cards about places and people into safe, unsure and unsafe, and say what to do next.', 'Use it to practice safety thinking and asking for help.', array['Teens', 'Groups']::text[], '30 minutes', 'Cards describe general situations, not anyone''s personal history. Players sort and say a next step. Remind the group that nobody shares personal details. Know your reporting duties if a disclosure occurs.', '[{"id": "f0", "type": "textarea", "label": "A card I sorted and why"}, {"id": "f1", "type": "textarea", "label": "A next step I could take"}, {"id": "f2", "type": "textarea", "label": "Who I can ask for help"}, {"id": "f3", "type": "textarea", "label": "One thing I learned"}]'::jsonb, array['sexual abuse', 'safety', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('coping-skill-fit-matrix', 'Coping Skill Fit Matrix', 'worksheet'::resource_kind, 'A matrix that matches coping skills to situations to show which fit best.', 'Use it to help a client pick skills that fit the moment.', array['Adults', 'Teens']::text[], '25 minutes', 'List situations and skills and rate how well each fits. Look for gaps in the matrix together. Ask the client to try one new skill a week and report back.', '[{"id": "f0", "type": "textarea", "label": "Situations that are hard for me:"}, {"id": "f1", "type": "textarea", "label": "Skills I have tried:"}, {"id": "f2", "type": "textarea", "label": "Which skills fit which situations:"}, {"id": "f3", "type": "textarea", "label": "A skill I want to add:"}]'::jsonb, array['coping skills', 'skills', 'toolbox']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('coping-thought-pocket-cards', 'Coping Thought Pocket Cards', 'cbt'::resource_kind, 'A set of small cards with helpful thoughts a client can read when stress rises.', 'Use it to give a client ready-made helpful thoughts for hard moments.', array['Adults', 'Teens']::text[], '25 minutes', 'The client writes thoughts in their own words and tests which feel believable. Keep three to five cards. Revisit and edit.', '[{"id": "f0", "type": "textarea", "label": "A thought that helps me when stressed:"}, {"id": "f1", "type": "textarea", "label": "When I will read it:"}, {"id": "f2", "type": "textarea", "label": "A thought that does not help, and what to say instead:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my cards:"}]'::jsonb, array['coping skills', 'coping thoughts', 'cue cards']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('values-guided-coping-choice-page', 'Values-Guided Coping Choice Page', 'act'::resource_kind, 'A page for choosing a coping action that fits a value, not only brings relief.', 'Use it to help a client choose coping that serves their life.', array['Adults']::text[], '25 minutes', 'Compare relief-only coping to values-guided coping. Ask which one the client wants more of. Both can be valid.', '[{"id": "f0", "type": "textarea", "label": "A hard moment this week:"}, {"id": "f1", "type": "textarea", "label": "What I did to cope:"}, {"id": "f2", "type": "textarea", "label": "Did it serve a value?"}, {"id": "f3", "type": "textarea", "label": "A choice I could try next time:"}]'::jsonb, array['coping skills', 'values', 'workability']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('coping-skills-treasure-map', 'Coping Skills Treasure Map', 'kids'::resource_kind, 'The child draws a treasure map where each stop hides a coping skill to try.', 'Use it to help a child learn a set of calming skills.', array['Children']::text[], '30 minutes', 'Draw a map with stops: breathing, drawing, hugging a toy. The child tries each one. The parent joins and later cues a stop when needed.', '[{"id": "f0", "type": "textarea", "label": "Draw my treasure map"}, {"id": "f1", "type": "textarea", "label": "The skill at each stop"}, {"id": "f2", "type": "textarea", "label": "My favorite skill"}, {"id": "f3", "type": "textarea", "label": "When my grown-up will remind me"}]'::jsonb, array['coping skills', 'calm down', 'children']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('skill-trade-market-game', 'Skill Trade Market Game', 'game'::resource_kind, 'Players trade skill cards by pitching why a skill would help in a situation.', 'Use it to build a shared set of coping skills.', array['Teens', 'Groups']::text[], '30 minutes', 'Each player holds a few skill cards and a situation. They pitch and trade. Debrief on what they picked and why.', '[{"id": "f0", "type": "textarea", "label": "The skill I traded for"}, {"id": "f1", "type": "textarea", "label": "Why it fits my situation"}, {"id": "f2", "type": "textarea", "label": "A skill I gave away"}, {"id": "f3", "type": "textarea", "label": "What I will practice"}]'::jsonb, array['coping skills', 'skills practice', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('avoidance-cost-tally-sheet', 'Avoidance Cost Tally Sheet', 'worksheet'::resource_kind, 'A sheet tallying what avoiding a feared thing costs in time, plans and things the client values.', 'Use it to help a client see the price of avoidance.', array['Adults', 'Teens']::text[], '25 minutes', 'List what the client avoids and what that gets in the way of. Then discuss what matters enough to take a step. Pace is the client''s and the clinician''s judgment.', '[{"id": "f0", "type": "textarea", "label": "What I avoid:"}, {"id": "f1", "type": "textarea", "label": "What it costs me:"}, {"id": "f2", "type": "textarea", "label": "What I would do if I did not avoid:"}, {"id": "f3", "type": "textarea", "label": "One tiny step toward that:"}]'::jsonb, array['phobias', 'avoidance', 'values']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('feared-outcome-prediction-review', 'Feared Outcome Prediction Review', 'cbt'::resource_kind, 'A review comparing what a client predicted would happen with what happened.', 'Use it to help a client learn from real outcomes.', array['Adults', 'Teens']::text[], '20 minutes', 'Record the prediction and how strongly they believed it, then what happened. Notice gaps. Plan the next small step with the client.', '[{"id": "f0", "type": "textarea", "label": "What I predicted:"}, {"id": "f1", "type": "textarea", "label": "How strongly I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "What I take from that:"}]'::jsonb, array['phobias', 'prediction', 'exposure']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('fear-and-courage-side-by-side-page', 'Fear and Courage Side-by-Side Page', 'act'::resource_kind, 'A page that places the fear and the courage to act beside each other.', 'Use it to help a client see that fear and courage can sit together.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw two columns: what fear says and what a valued action looks like. Let both be present. Choose a small step.', '[{"id": "f0", "type": "textarea", "label": "What fear tells me:"}, {"id": "f1", "type": "textarea", "label": "What I care about:"}, {"id": "f2", "type": "textarea", "label": "A step with fear along for the ride:"}, {"id": "f3", "type": "textarea", "label": "Who might cheer me on:"}]'::jsonb, array['phobias', 'courage', 'acceptance']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('brave-steps-stepping-stones-craft', 'Brave Steps Stepping Stones Craft', 'kids'::resource_kind, 'The child makes paper stepping stones for each small brave step and walks across them.', 'Use it to help a child see small steps toward a feared thing.', array['Children']::text[], '30 minutes', 'Cut stones from paper and write a tiny step on each. The child steps on them one at a time at their own pace. The parent cheers and does not push. Choose steps with the clinician.', '[{"id": "f0", "type": "textarea", "label": "Draw my stepping stones"}, {"id": "f1", "type": "textarea", "label": "The smallest step"}, {"id": "f2", "type": "textarea", "label": "The biggest step at the end"}, {"id": "f3", "type": "textarea", "label": "How my grown-up helps"}]'::jsonb, array['phobias', 'fear ladder', 'craft']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('imagination-ladder-spinner', 'Imagination Ladder Spinner', 'game'::resource_kind, 'A spinner game where players imagine small steps from easy to hard toward a feared thing.', 'Use it to practice talking about fear steps with humor.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Make a spinner with ladder rungs from easy to hard. The player describes the step. No one is asked to do a step they have not chosen. Debrief on feelings.', '[{"id": "f0", "type": "textarea", "label": "The rung I landed on"}, {"id": "f1", "type": "textarea", "label": "What I imagined"}, {"id": "f2", "type": "textarea", "label": "How my body felt"}, {"id": "f3", "type": "textarea", "label": "What I could try for real"}]'::jsonb, array['phobias', 'hierarchy', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('body-respect-weekly-page', 'Body Respect Weekly Page', 'worksheet'::resource_kind, 'A weekly page for noticing times a client treated their body with respect.', 'Use it to help a client focus on care and function.', array['Adults', 'Teens']::text[], 'One week', 'Ask for one act of respect a day, like rest or stretching. Keep away from appearance goals. Review patterns together.', '[{"id": "f0", "type": "textarea", "label": "One way I respected my body today:"}, {"id": "f1", "type": "textarea", "label": "What my body let me do:"}, {"id": "f2", "type": "textarea", "label": "How I spoke about my body:"}, {"id": "f3", "type": "textarea", "label": "What I want to repeat:"}]'::jsonb, array['body image', 'self-care', 'respect']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('appearance-thought-check-page', 'Appearance Thought Check Page', 'cbt'::resource_kind, 'A page for catching harsh appearance thoughts and trying kinder, fairer ones.', 'Use it to help a client respond to harsh thoughts about appearance.', array['Adults', 'Teens']::text[], '25 minutes', 'Capture the thought and the moment it showed up. Ask what a friend would say. Move attention toward what the body does.', '[{"id": "f0", "type": "textarea", "label": "The moment and the thought:"}, {"id": "f1", "type": "textarea", "label": "How it made me feel:"}, {"id": "f2", "type": "textarea", "label": "What a friend would say:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought:"}]'::jsonb, array['body image', 'self-talk', 'cognitive restructuring']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('body-kindness-actions-values-page', 'Body Kindness Actions Values Page', 'act'::resource_kind, 'A page connecting a value, like care, to small actions that are kind to the body.', 'Use it to help a client act on values instead of appearance worries.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client would do if appearance worries were quieter. Choose one such action. Worries may come along.', '[{"id": "f0", "type": "textarea", "label": "What I would do if worries were quieter:"}, {"id": "f1", "type": "textarea", "label": "A value behind it:"}, {"id": "f2", "type": "textarea", "label": "A kind action for my body:"}, {"id": "f3", "type": "textarea", "label": "What I will do with worries that come along:"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('things-my-body-helps-me-do-mural', 'Things My Body Helps Me Do Mural', 'kids'::resource_kind, 'The child draws a mural of everything their body helps them do.', 'Use it to help a child value what bodies do.', array['Children']::text[], '30 minutes', 'Roll out paper and draw activities: running, hugging, dancing. The parent adds one. Talk about function, not looks. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my mural"}, {"id": "f1", "type": "textarea", "label": "Three things my body helps me do"}, {"id": "f2", "type": "textarea", "label": "My favorite one"}, {"id": "f3", "type": "textarea", "label": "What my grown-up adds"}]'::jsonb, array['body image', 'strengths', 'art']::text[], '2026-10-29T15:00:00+00:00'::timestamptz),
  ('media-message-detective-game', 'Media Message Detective Game', 'game'::resource_kind, 'Players examine ads and images as detectives and ask who made them and why.', 'Use it to build media literacy and critical thinking about appearance messages.', array['Teens', 'Groups']::text[], '30 minutes', 'Bring ads or screenshots. Detectives ask who made it and what it wants. Skip anything that could be triggering. Debrief on what they notice.', '[{"id": "f0", "type": "textarea", "label": "The message I looked at"}, {"id": "f1", "type": "textarea", "label": "Who made it and why"}, {"id": "f2", "type": "textarea", "label": "How it made me feel"}, {"id": "f3", "type": "textarea", "label": "What I will do when I see one"}]'::jsonb, array['body image', 'media literacy', 'game']::text[], '2026-10-29T15:00:00+00:00'::timestamptz)
